if (!function_exists('render_shift_badge')) {
    function render_shift_badge(string $type, bool $withTime = false, string $timeText = ''): string {
        $t = strtolower($type);
        if ($t === 'oh' || $t === 'office_hour') {
            $icon = app_icon('building', 14, 'me-1');
            $label = 'Office Hour (OH)';
            $cls = 'shift-badge shift-badge-oh';
        } elseif ($t === 'malam') {
            $icon = app_icon('moon', 14, 'me-1');
            $label = 'Shift Malam';
            $cls = 'shift-badge shift-badge-malam';
        } else {
            $icon = app_icon('sun', 14, 'me-1');
            $label = 'Shift Pagi';
            $cls = 'shift-badge shift-badge-pagi';
        }

        $html = '<span class="' . $cls . '" style="display: inline-flex; align-items: center; gap: 5px;">' . $icon . '<span>' . htmlspecialchars($label) . '</span></span>';
        if ($withTime && !empty($timeText)) {
            $html .= '<div style="font-size: 0.72rem; color: var(--text-subtle); margin-top: 3px;">' . htmlspecialchars($timeText) . '</div>';
        }
        return $html;
    }
}
